// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Anatomy is the study of body structure; physiology is how it works. First, let's learn to speak the language.","blocks":[{"t":"p","text":"The body is organized from chemicals to cells, tissues, organs, organ systems and the whole organism."},{"t":"key","text":"Anatomical position: standing upright, facing forward, arms at sides, palms forward. All directions are described from this position."},{"t":"p","text":"Directional terms:"},{"t":"list","items":["Superior (above) and inferior (below).","Anterior (front) and posterior (back).","Medial (toward the midline) and lateral (away from it).","Proximal (closer to where a limb attaches) and distal (farther)."]},{"t":"p","text":"Body planes: sagittal (left and right), frontal (front and back) and transverse (top and bottom). Body cavities include the cranial, thoracic and abdominopelvic cavities."}]},{"say":"The body works constantly to keep its internal conditions stable. Tissues are the teams that make it possible.","blocks":[{"t":"key","text":"Homeostasis is maintained mostly by negative feedback: a receptor detects a change, a control center (often the brain) responds, and an effector reverses the change."},{"t":"p","text":"Example: when body temperature rises, sweat glands release sweat, and blood vessels near the skin widen to release heat."},{"t":"p","text":"Four tissue types:"},{"t":"list","items":["Epithelial: covers surfaces and lines organs (skin, stomach lining).","Connective: supports and connects (bone, cartilage, blood, fat).","Muscle: contracts to produce movement (skeletal, cardiac, smooth).","Nervous: sends electrical signals (neurons)."]},{"t":"lab","kind":"lab","title":"Cooling down after exercise","aim":"Measure core body temperature after exercise. How does negative feedback bring it back to 37 °C?","sets":[{"name":"t","start":5,"label":"Time after exercise (min)","min":0,"max":60,"step":1},{"name":"rise","start":2,"label":"Temperature rise from exercise (°C)","min":0.5,"max":3,"step":0.5}],"outs":[{"name":"T","expr":"37 + rise*exp(-t/12)","label":"Core temperature (°C)"}],"steps":["Record the temperature every 10 minutes."],"noise":1,"result":"Sweating and wider skin blood vessels remove heat fastest when the temperature is furthest from the set point, so it returns smoothly to about 37 °C. That's negative feedback.","plot":{"x":"t","y":"T"}}]}],[{"say":"Your skeleton supports you, protects your organs, and even makes your blood cells.","blocks":[{"t":"p","text":"The adult skeleton has 206 bones, divided into the axial skeleton (skull, spine, ribs) and the appendicular skeleton (limbs, shoulders, hips)."},{"t":"key","text":"Functions of bones: support, protection, movement (with muscles), mineral storage (calcium) and blood cell production in red bone marrow."},{"t":"p","text":"Bone is living tissue constantly remodeled by osteoblasts (build bone) and osteoclasts (break it down). Joints connect bones: immovable (skull sutures), slightly movable (vertebrae), and freely movable synovial joints (knee, shoulder). Ligaments connect bone to bone."},{"t":"p","text":"Weight-bearing exercise and calcium help keep bones strong; osteoporosis weakens them."}]},{"say":"Muscles move you, pump your blood and push food through your body. Let's see how they contract.","blocks":[{"t":"key","text":"Three muscle types: skeletal (voluntary, attached to bones by tendons), cardiac (involuntary, only in the heart), and smooth (involuntary, in organs like the stomach and blood vessels)."},{"t":"p","text":"Muscles can only pull, not push, so they work in pairs: when the biceps contracts, the triceps relaxes."},{"t":"p","text":"Sliding filament theory: inside muscle fibers, actin and myosin filaments slide past each other to shorten the muscle. This requires ATP and calcium, triggered by signals from motor neurons."},{"t":"p","text":"Exercise builds muscle strength and endurance; muscles weaken without use (atrophy)."},{"t":"lab","kind":"lab","title":"The forearm as a lever","aim":"How hard must the biceps pull to hold a weight in your hand?","sets":[{"name":"m","start":5,"label":"Mass held (kg)","min":1,"max":20,"step":1},{"name":"dl","start":35,"label":"Hand distance from elbow (cm)","min":20,"max":40,"step":1},{"name":"di","start":4,"label":"Biceps attachment distance (cm)","min":3,"max":6,"step":0.5}],"outs":[{"name":"F","expr":"m*g*dl/di","label":"Biceps force (N)"},{"name":"ratio","expr":"dl/di","label":"Force multiplier"}],"steps":["Record the biceps force for 4 masses.","Then move the attachment point farther from the elbow."],"noise":2,"result":"The forearm is a third-class lever: the muscle attaches close to the elbow, so it must pull about 9 times the load. The trade-off is speed and range of motion at the hand.","plot":{"x":"m","y":"F"}}]}],[{"say":"The nervous system is your body's high-speed communication network.","blocks":[{"t":"p","text":"The central nervous system (CNS) is the brain and spinal cord. The peripheral nervous system (PNS) includes nerves throughout the body."},{"t":"key","text":"Neurons send electrical impulses (action potentials) along axons. At synapses, they release neurotransmitters to signal the next cell."},{"t":"p","text":"Parts of the brain: cerebrum (thinking, senses, voluntary movement), cerebellum (balance and coordination), and brainstem (breathing, heart rate). The autonomic nervous system controls involuntary functions: sympathetic (fight-or-flight) and parasympathetic (rest-and-digest)."},{"t":"p","text":"A reflex arc lets the spinal cord respond quickly without waiting for the brain, like pulling your hand from a hot stove."},{"t":"lab","kind":"lab","title":"Ruler drop reaction time","aim":"Catch a falling ruler and use how far it fell to calculate your reaction time.","sets":[{"name":"d","start":15,"label":"Distance the ruler fell (cm)","min":5,"max":30,"step":1}],"outs":[{"name":"t","expr":"sqrt(2*d/100/g)*1000","label":"Reaction time (ms)"}],"steps":["Record the reaction time for at least 4 catches.","A nerve impulse travels about 1 m in 10–20 ms. What else takes time?"],"noise":2,"result":"Typical reaction times are 150–250 ms. Only a small part is nerve conduction; most is the brain processing the signal (synapses) before sending a message to the hand muscles.","plot":{"x":"d","y":"t"}}]},{"say":"The endocrine system sends slower but longer-lasting messages using hormones carried in the blood.","blocks":[{"t":"key","text":"Glands release hormones into the bloodstream, which travel to target cells with matching receptors."},{"t":"p","text":"Major glands and hormones:"},{"t":"list","items":["Pituitary: the \"master gland,\" controlled by the hypothalamus; releases growth hormone and hormones that control other glands.","Thyroid: thyroxine regulates metabolism.","Adrenal glands: adrenaline (fight-or-flight) and cortisol (stress).","Pancreas: insulin lowers blood sugar; glucagon raises it.","Ovaries and testes: estrogen, progesterone and testosterone."]},{"t":"p","text":"Diabetes happens when the body doesn't make enough insulin (type 1) or doesn't respond to it well (type 2)."}]}],[{"say":"Your heart beats about 100,000 times a day, pumping blood through a network of vessels that would stretch around Earth twice.","blocks":[{"t":"key","text":"Blood flow: body → right atrium → right ventricle → lungs (pulmonary circuit) → left atrium → left ventricle → body (systemic circuit)."},{"t":"p","text":"Valves keep blood flowing in one direction. The left ventricle has the thickest walls because it pumps blood to the whole body."},{"t":"list","items":["Arteries carry blood away from the heart under high pressure.","Veins carry blood back to the heart and have valves.","Capillaries are tiny vessels where gases and nutrients are exchanged."]},{"t":"p","text":"Blood contains red blood cells (carry oxygen with hemoglobin), white blood cells (fight infection), platelets (clotting) and plasma."}]},{"say":"Breathing brings in oxygen your cells need and removes carbon dioxide they produce.","blocks":[{"t":"key","text":"Air path: nose/mouth → pharynx → larynx → trachea → bronchi → bronchioles → alveoli. Gas exchange happens in the alveoli, tiny air sacs surrounded by capillaries."},{"t":"p","text":"Oxygen diffuses from alveoli into the blood; carbon dioxide diffuses from blood into the alveoli to be exhaled."},{"t":"p","text":"The diaphragm contracts and moves down to pull air in (inhalation); it relaxes and moves up to push air out (exhalation)."},{"t":"p","text":"The brainstem controls breathing rate mainly by sensing CO₂ levels in the blood. Smoking damages alveoli and cilia that clean the airways."},{"t":"lab","kind":"lab","title":"Spirometer and breathing","aim":"Measure breathing rate and tidal volume to find how much air moves in and out each minute.","sets":[{"name":"f","start":12,"label":"Breaths per minute","min":8,"max":40,"step":1},{"name":"TV","start":0.5,"label":"Tidal volume (L)","min":0.3,"max":3,"step":0.1}],"outs":[{"name":"VE","expr":"f*TV","label":"Minute ventilation (L/min)"},{"name":"VA","expr":"f*(TV - 0.15)","label":"Air reaching alveoli (L/min)"}],"steps":["Record ventilation at rest (12 breaths, 0.5 L), then during exercise.","Compare fast shallow breathing with slow deep breathing at the same ventilation."],"noise":3,"result":"Ventilation = rate × tidal volume, rising from about 6 L/min to over 100 L/min in hard exercise. About 0.15 L of each breath stays in the airways (dead space), so deep breaths are more efficient.","plot":{"x":"f","y":"VE"}}]}],[{"say":"Your digestive system breaks food into nutrients, and your kidneys filter waste from your blood.","blocks":[{"t":"key","text":"Digestive path: mouth → esophagus → stomach → small intestine → large intestine. Mechanical digestion breaks food physically; chemical digestion uses enzymes."},{"t":"list","items":["Mouth: saliva (amylase) begins breaking down starch.","Stomach: acid and pepsin break down proteins.","Small intestine: most digestion and absorption happen here, through villi that increase surface area. The liver makes bile to break up fats, and the pancreas supplies enzymes.","Large intestine: absorbs water."]},{"t":"p","text":"The urinary system filters blood through the kidneys' nephrons, removing wastes like urea and balancing water and salts. Urine travels through the ureters to the bladder."},{"t":"lab","kind":"lab","title":"Bile and surface area","aim":"Break a 1 cm cube of fat into smaller pieces, as bile does, and calculate the surface area lipase can work on.","sets":[{"name":"s","start":5,"label":"Piece size (mm)","min":0.1,"max":10,"step":0.1}],"outs":[{"name":"SA","expr":"6*10^3/s/100","label":"Total surface area (cm²)"},{"name":"n","expr":"(10/s)^3","label":"Number of pieces"}],"steps":["Record the surface area for at least 4 piece sizes."],"noise":1,"result":"Halving the piece size doubles the total surface area. Bile emulsifies fat into tiny droplets, so lipase has far more surface to act on and digestion is much faster.","plot":{"x":"s","y":"SA"}}]},{"say":"Your immune system defends you against germs with layers of protection.","blocks":[{"t":"key","text":"Lines of defense:"},{"t":"list","items":["First: barriers like skin, mucus and stomach acid.","Second: nonspecific responses like inflammation, fever and white blood cells that engulf invaders (phagocytes).","Third: specific (adaptive) immunity. B cells make antibodies that tag specific pathogens; T cells destroy infected cells and coordinate the response."]},{"t":"p","text":"Memory cells remember pathogens, so a second infection is fought off faster. Vaccines train memory cells safely."},{"t":"p","text":"Problems include allergies (overreaction to harmless substances), autoimmune diseases (attacking the body's own cells) and immunodeficiency (like HIV weakening T cells)."}]}]];
export default text;
